def run_len(s: str) -> int:
    """Return the length of the longest run of identical characters in s."""
    best = 0
    cur = 0
    prev = None
    for ch in s:
        if ch == prev:
            cur += 1
        else:
            prev = ch
            cur = 1
        if cur > best:
            best = cur
    return best
